    "Notes": "переосмыслено в латинском языке слово musculus – мускул. То же самое произошло и с общеславянским словом мышь: движение мускулов под кожей так напоминало мышиную беготню, что и в русском языке произошло такое же переосмысление. Любопытно другое – и русское слово мышь восходит к латинскому mus. Такое двукратное заимствование привело к существованию в русском языке двух однокоренных слов (мышца и мускул), имеющих практически одинаковое значение.",
